const doc = `${cwd}/requirements.json`
const env = { ...process.env, SYMSPEC_EMBED_STUB: '1', NO_COLOR: '1', CI: '1' }
function cli(args) {
  const result = spawnSync(process.execPath, [binary, ...args], { cwd, env, encoding: 'utf8' })
  return { args, status: result.status, stdout: result.stdout, stderr: result.stderr }
}
const init = cli(['init', doc])
assert.equal(init.status, 0, init.stderr)
const rejected = cli(['state-initial', 'undeclared_flag', '--file', doc])
const envelope = JSON.parse(rejected.stdout)
assert.equal(envelope.type, 'error')
const suggestion = envelope.suggestions.find(text => text.includes('--type bool|int|enum'))
assert.ok(suggestion, rejected.stdout)
const emitted = suggestion.match(/`(symspec [^`]+)`/)[1]
// Substitute only the explicit <name> slot. Leave the published choice token verbatim.
const substituted = emitted.replace('<name>', 'undeclared_flag')
