  'symspec() { printf "symspec-arg:<%s>\\n" "$@" >&2; }',
  'int() { printf "unexpected-command:int\\n" >&2; }',
  'enum() { printf "unexpected-command:enum\\n" >&2; }',
  substituted,
].join('\n')
