  head: '6f7e95799ae7e107b99aee110aea5096469918f8',
  node: process.version,
  init,
  rejected,
  emitted,
  substituted,
  syntax: { status: syntax.status, stderr: syntax.stderr },
  shell: { status: shell.status, stdout: shell.stdout, stderr: shell.stderr },
